import json
d=json.load(open('factors/mom_10d_skip5.json'))
def skim(o, depth=0, maxd=4):
    if depth>maxd: return
    if isinstance(o, dict):
        for k,v in o.items():
            if isinstance(v,(dict,list)):
                print('  '*depth + f'{k}:')
                skim(v, depth+1, maxd)
            else:
                s=str(v)
                print('  '*depth + f'{k}: {s[:120]}')
    elif isinstance(o, list):
        print('  '*depth + f'[list len={len(o)}]')
        if o: skim(o[0], depth+1, maxd)
skim(d)
