import json
d=json.load(open('factors/mom_10d_skip5.json'))
# show structure without the huge artifact data
def short(o, depth=0):
    if isinstance(o, dict):
        return {k: short(v, depth+1) for k,v in o.items() if k!='data'}
    if isinstance(o, list):
        return [short(x, depth+1) for x in o[:5]] + (['...'] if len(o)>5 else [])
    return o
print(json.dumps(short(d), indent=1))
print('artifact data len:', len(d['validation']['signal_artifact']['data']))
